import { projectStore, IProject } from '@droid/project-v2-interface';
import { Dispatcher, loadI18nValue, Log, toProxy } from '@fanfanlo';
import { IProjectEditInfo } from './IProjectEditInfo.intf';
import toast from 'react-hot-toast';
import { syncToServer } from '../utils/projectSyncUtils';
import {user} from '@app/model'
const map: { [key: string]: IProjectEditInfo } = toProxy({});
const dispatcher = new Dispatcher();
const projectSavedEvent = 'project-saved';
export const editProjectInfoUtils = {
  edit: (project: IProject) => {
    // const info = map[project.ulid] || (map[project.ulid] = createProjectEditInfo(project));
    const info = (map[project.ulid] = createProjectEditInfo(project));
    return info;
  },
  getEditInfoByUlid: (ulid: string) => {
    if (map[ulid]) return map[ulid];
    const project = projectStore.findProject(ulid);
    if (project) return (map[ulid] = createProjectEditInfo(project));
    return null;
  },
  listenProjectSaved: (fn: (project: IProject) => void) => {
    return dispatcher.addListener(projectSavedEvent, fn);
  },
};

export function createProjectEditInfo(project: IProject): IProjectEditInfo {
  const info = toProxy({
    project,
    askStay: false,
    giveup: false,
    updated: false,
    historyId: 0,
    testTime: new Date().toLocaleString(),
    save: async () => {
      info.updated = false;
      info.askStay = false;
      info.giveup = false;
      projectStore.saveProject(project);
      dispatcher.dispatch(projectSavedEvent, project);
      const s = await loadI18nValue('droid-project/project/manager/content', 'edit-project-info-utils.projectSaved');
      toast.success(s);
      // 如果开启了同步到服务器，则同步
      const settings = projectStore.getProjectSettings(project.ulid!);
      console.log('aaaaaaaaaaaaa', user.data.storeData.user_token, settings)
      if (user.data.storeData.user_token &&  settings && settings.syncToServer) {
        syncToServer(project);
      }
    },
  });
  return info;
}
