import { IRequestParams, IResultContent, request } from "@fanfanlo";
import { IRequestOptions } from "../IRequestOptions";
import { tms } from "../tms";
import type { IProjectProject, IUpdateProjectData, IUpdateProjectResult } from "./types";

/**
 * 更新项目的请求参数
 */
export interface IUpdateProjectParams extends IRequestParams {
    data: IUpdateProjectData;
}

/**
 * 更新项目的返回结果
 */
export interface IUpdateProjectResultBody extends IResultContent {
    isOk: boolean;
    msg: string;
    project?: IProjectProject;
    changes?: Record<string, any>;
    deletedChildren?: string[];
    createdChildren?: string[];
    oldVisibility?: string;
}

/**
 * 更新项目
 * @param opts 请求选项
 * @returns 更新结果
 */
export async function updateProject(opts: IRequestOptions<IUpdateProjectParams>) {
    console.log('[updateProject] 开始更新项目, params:', JSON.stringify(opts.params));

    const res = await request<IUpdateProjectResultBody>(
        tms.TProject,
        tms.MProjectUpdateProject,
        opts.params,
        opts.gateway,
        opts.handler
    );

    if (res.shellIsOk) {
        console.log('[updateProject] 请求成功, shellIsOk:', res.shellIsOk);
    } else {
        console.log('[updateProject] 请求失败, shellIsOk:', res.shellIsOk, 'err:', res.err);
    }

    if (res.dataIsOk) {
        console.log('[updateProject] 数据正常, dataIsOk:', res.dataIsOk);
    } else {
        console.log('[updateProject] 数据异常, dataIsOk:', res.dataIsOk, 'errMsg:', res.data?.errMsg, 'errCode:', res.data?.errCode);
    }

    if (res.data) {
        if (res.data.isOk) {
            console.log('[updateProject] 更新成功, project.uuid:', res.data.project?.uuid);
            console.log('[updateProject] 变更信息:', JSON.stringify(res.data.changes));
            console.log('[updateProject] 删除的子级:', res.data.deletedChildren);
            console.log('[updateProject] 创建的子级:', res.data.createdChildren);
        } else {
            console.log('[updateProject] 更新失败, msg:', res.data.msg);
        }
    } else {
        console.log('[updateProject] 无返回数据');
    }

    return res;
}

export default updateProject;
